/**
 * Expo config plugin: smaller Android release builds.
 *
 * - R8 code shrinking and resource shrinking in release builds (the dex alone was ~50 MB raw).
 * - Compressed native libraries in the APK (`useLegacyPackaging`), so the download is smaller.
 * - Conservative keep rules for libraries that reach Java/Kotlin code through JNI or reflection,
 *   so R8 cannot strip classes that are only referenced from C++ or by name.
 *
 * android/ is generated by `expo prebuild`, so these settings must live here, not in android/.
 */
const { withGradleProperties, withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const GRADLE_PROPERTIES = {
  'android.enableMinifyInReleaseBuilds': 'true',
  'android.enableShrinkResourcesInReleaseBuilds': 'true',
  'expo.useLegacyPackaging': 'true',
};

const KEEP_RULES_MARKER = '# Lectio: keep rules (plugins/with-android-release-size.js)';
const KEEP_RULES = `
${KEEP_RULES_MARKER}
# Software Mansion libraries call into Java/Kotlin from C++ (JNI) and by reflection.
-keep class com.swmansion.** { *; }
# Expo modules are discovered by name at runtime.
-keep class expo.modules.** { *; }
-keep class * extends expo.modules.kotlin.modules.Module { *; }
# React Native TurboModules / codegen specs looked up through JNI.
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.jni.** { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.common.internal.DoNotStrip *; }
-dontwarn com.swmansion.**
-dontwarn expo.modules.**
`;

function withReleaseGradleProperties(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(GRADLE_PROPERTIES)) {
      const existing = cfg.modResults.find((item) => item.type === 'property' && item.key === key);
      if (existing) existing.value = value;
      else cfg.modResults.push({ type: 'property', key, value });
    }
    return cfg;
  });
}

function withKeepRules(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
      if (!current.includes(KEEP_RULES_MARKER)) fs.writeFileSync(file, current + KEEP_RULES);
      return cfg;
    },
  ]);
}

module.exports = function withAndroidReleaseSize(config) {
  return withKeepRules(withReleaseGradleProperties(config));
};
